const experiences={first:{title:'Todo surfista<br>já foi iniciante.',level:'PARA QUEM VAI COMEÇAR',number:'/ 01',tag:'SEU PRIMEIRO DROP COMEÇA AQUI',image:'assets/session.jpg',alt:'Grupo com pranchas de surf na água',description:'Conheça a prancha, sinta o movimento da água e descubra a alegria de ficar em pé pela primeira vez. Sem cobrança. Com orientação a cada remada.',duration:'Uma manhã, sem pressa',focus:'Base, remada e primeiras ondas',vibe:'Turma pequena, grandes descobertas',name:'Primeira onda'},flow:{title:'Menos pensar.<br>Mais sentir.',level:'PARA QUEM QUER EVOLUIR',number:'/ 02',tag:'SUA PRÓXIMA ONDA É DIFERENTE',image:'assets/ocean.jpg',alt:'Surfista em pé deslizando pela onda',description:'Ajuste sua leitura do mar, encontre o melhor posicionamento e ganhe fluidez. Uma experiência para quem já pega ondas e quer construir mais confiança no próprio surf.',duration:'Uma sessão no seu ritmo',focus:'Posicionamento, linha e fluidez',vibe:'Atenção aos detalhes, liberdade no surf',name:'Encontre o flow'},free:{title:'O melhor plano?<br>Estar lá fora.',level:'PARA QUEM QUER SE CONECTAR',number:'/ 03',tag:'BOAS HISTÓRIAS VÊM DE DIAS ASSIM',image:'assets/island.webp',alt:'Paisagem costeira com coqueiros e skatista',description:'Um encontro com o lado simples da vida: praia, movimento e boas conversas. A cultura do surf em um dia para respirar, conhecer gente e deixar o relógio um pouco de lado.',duration:'Um dia para desconectar',focus:'Praia, movimento e convivência',vibe:'Sol, ar livre e gente boa',name:'Dia de mar'}};
let selected='first';const tabs=[...document.querySelectorAll('[role="tab"]')];
function setExperience(key){selected=key;const data=experiences[key];tabs.forEach(tab=>{const active=tab.dataset.experience===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1});document.getElementById('experience-panel').setAttribute('aria-labelledby','tab-'+key);document.getElementById('experience-title').innerHTML=data.title;['level','number','tag','description','duration','focus','vibe'].forEach(field=>document.getElementById('experience-'+field).textContent=data[field]);const img=document.getElementById('experience-img');img.src=data.image;img.alt=data.alt;document.getElementById('level').value=key}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setExperience(tab.dataset.experience));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();setExperience(tabs[next].dataset.experience)}})});
const menu=document.querySelector('.menu-toggle'),navigation=document.getElementById('navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');navigation.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');navigation.classList.toggle('open',open)});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});
let suggestion='';document.getElementById('session-form').addEventListener('submit',e=>{e.preventDefault();const data=experiences[document.getElementById('level').value];const company=document.getElementById('company').value;const descriptions={solo:'Por conta, aberto a novas conexões.',pair:'Em dupla, dividindo cada descoberta.',friends:'Com a galera, criando boas histórias.'};const title=data.name+' · '+({solo:'sua jornada',pair:'em dupla',friends:'com amigos'}[company]);const copy=data.duration+'. '+descriptions[company]+' Foco: '+data.focus.toLowerCase()+'.';suggestion='Minha experiência MARÉ: '+title+'\n'+copy;document.getElementById('result-title').textContent=title;document.getElementById('result-copy').textContent=copy;document.getElementById('copy-status').textContent='';const result=document.getElementById('session-result');result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})});
document.getElementById('copy-session').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(suggestion);document.getElementById('copy-status').textContent='Sugestão copiada!'}catch{document.getElementById('copy-status').textContent='Selecione o texto da sugestão para copiar.'}});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
